+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.sidenav.SideNavItem;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import org.jooq.DSLContext;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VETS;
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VET_SPECIALTIES;
+import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+/**
+ * UC-002: View Veterinarians.
+ */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-003")
+    void gridListsVetsWithSpecialties() {
+        // Reached anonymously through the navigation bar, covering BR-003.
+        navigate(VetView.class);
+
+        Grid<Vet> grid = assertDoesNotThrow(() -> find(Grid.class).single(),
+                "Expected exactly one veterinarians grid");
+        assertEquals(6, grid.getLazyDataView().getItems().count());
+        assertEquals("none", rowSpecialties(grid, "Carter"));
+        assertEquals("radiology", rowSpecialties(grid, "Leary"));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesAreOrderedAlphabetically() {
+        navigate(VetView.class);
+
+        Grid<Vet> grid = find(Grid.class).single();
+        assertEquals("dentistry, surgery", rowSpecialties(grid, "Douglas"));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void rowsAreFetchedLazily() {
+        for (int i = 0; i < 100; i++) {
+            dsl.insertInto(VETS).set(VETS.FIRST_NAME, "Vet" + i).set(VETS.LAST_NAME, "Zzz" + i).execute();
+        }
+        navigate(VetView.class);
+
+        Grid<Vet> grid = find(Grid.class).single();
+        assertEquals(106, grid.getLazyDataView().getItems().count());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void noVetsRendersEmptyGrid() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        navigate(VetView.class);
+
+        Grid<Vet> grid = assertDoesNotThrow(() -> find(Grid.class).single(),
+                "Expected the veterinarians grid even without vets");
+        assertTrue(grid.getLazyDataView().getItems().findAny().isEmpty(), "Expected no rows");
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void navigationLinkLeadsToVets() {
+        navigate(VetView.class);
+
+        assertDoesNotThrow(() -> find(SideNavItem.class)
+                        .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Missing Veterinarians navigation item");
+    }
+
+    private String rowSpecialties(Grid<Vet> grid, String lastName) {
+        Vet vet = grid.getLazyDataView().getItems()
+                .filter(v -> v.lastName().equals(lastName)).findFirst().orElseThrow();
+        return vet.specialties().isEmpty() ? "none" : String.join(", ", vet.specialties());
+    }
+}
